#include <iostream>
#include <string>
#include <cctype>

using namespace std;

bool isUserName(const string& s) {
    if (s.empty() || s.size() > 16) return false;

    for (unsigned char c : s) {
        if (!isalnum(c) && c != '_') return false;
    }
    return true;
}

bool isHostName(const string& s) {
    if (s.empty() || s.size() > 32) return false;

    size_t start = 0;
    while (true) {
        size_t dot = s.find('.', start);
        string part = s.substr(start, dot == string::npos ? string::npos : dot - start);

        if (!isUserName(part)) return false;
        if (dot == string::npos) break;

        start = dot + 1;
    }
    return true;
}

bool solve(const string& s) {
    size_t at = s.find('@');
    if (at == string::npos || s.find('@', at + 1) != string::npos) return false;
    if (!isUserName(s.substr(0, at))) return false;

    string rest = s.substr(at + 1);
    size_t slash = rest.find('/');

    if (slash == string::npos) {
        return isHostName(rest);
    }

    if (rest.find('/', slash + 1) != string::npos) return false;

    string hostname = rest.substr(0, slash);
    string resource = rest.substr(slash + 1);

    return isHostName(hostname) && isUserName(resource);
}

int main() {
    string s;
    cin >> s;

    cout << (solve(s) ? "YES" : "NO") << '\n';
    return 0;
}

